q=json.loads((K/'queue.json').read_text());assert q['active_batch'] is None;assert not (B/'batch.json').exists();B.mkdir(parents=True,exist_ok=True)
rows=[(406, 'the-still-back-of-a-shell', 'The still back of a shell', 'After an accumulation of inward landscapes and loneliness, the poem settles on whiteness and the still back of a shell. One quiet shell concentrates that ending without inventing a geographical view of Bhitarkanika or a collage of its earlier images.', 'Original horizontal 3:2 spare graphite and chalky white gouache on warm grey ivory paper. One small closed pale bivalve shell rests on ordinary damp sand left of center, seen low and obliquely, convex ridged back upward. Unequal worn radial ribs, a subtle grey line where the two halves meet, tiny contact shadow, restrained damp sand mark at its base. The shell is modest, not a giant flawless spiral or pearl display. The rest of the surface remains broad quiet grey-beige wash; no ocean horizon, bird, boat, flowers, person, jewel, writing or dramatic spotlight. Slight diffuse cool daylight, a feeling of stillness after too much feeling; not a death scene or scientific species plate.'), (409, 'a-little-light-between-tasks', 'A little light between tasks', 'The woman writing poetry finds an inner life amid cooking, household duties and judgment. A patch of skylight in an ordinary kitchen holds a moment she might claim for herself, without inventing the poet’s face or decorating domestic work.', 'Original horizontal 3:2 restrained matte gouache interior in muted earth and pale blue-grey. An ordinary small kitchen wall and the edge of a plain worktop, a compact high rectangular skylight opening partly cropped near upper left casts one pale patch of daylight onto the otherwise quiet wall. At the far lower left, only a cropped portion of a dark cooking pan and a plain resting wooden spoon indicate interrupted work; utensils are subordinate and not arranged as a still-life display. Geometry of wall, opening and worktop coherent; soft reflected light, no dramatic god rays, text, steam calligraphy, decorative herbs, antique props, books or identifiable people. Large still wall area at right; emotional focus is the pocket of inward freedom in daily work, not a luxury kitchen.'), (410, 'where-a-meeting-was-promised', 'Where a meeting was promised', 'The lovers once promised to meet in the shade of a mahua tree under moonlight, but distance remains. A quiet space beneath an ordinary tree preserves that unfulfilled meeting without staging a couple or turning longing into a romantic spectacle.', 'Original horizontal 3:2 low-density charcoal and soft indigo watercolor night study. Cropped base and lower trunk of a mature broadleaf tree at far left, with a few roots meeting level bare ground. A pool of weak cool moonlight falls across the ground toward center; irregular leaf shadows interrupt it, with a little of the overhead foliage suggested along the top edge. Quiet dark blue-grey space at right, still readable and never black horror. No visible moon, stars, glowing flowers, swing, shrine, bench, person or footprints; no exact botanical or documentary location claim. The empty space is where a meeting was promised. Believable root contact and one consistent light direction, selective charcoal marks close to the trunk, no theatrical fog or glitter.')]
items=[]
for pid,ident,title,reason,scene in rows:
 p=S/f'content/editions/issue-19/poem-{pid}.json';d=json.loads(p.read_text());snapshot=B/f'poem-{pid}.json';snapshot.write_bytes(p.read_bytes())
